from datetime import datetime, timedelta
import random


def get_weather_forecast(city: str) -> dict:
    """Generates a 10-hour temperature time series forecast for a given city."""
    forecast = []
    current_time = datetime.now()

    # Starting with a baseline temperature between 10°C and 20°C
    current_temp = random.uniform(10.0, 20.0)

    for hour in range(1, 11):
        future_time = current_time + timedelta(hours=hour)

        # Simulate slight hourly temperature fluctuations (-1.5°C to +1.5°C)
        current_temp += random.uniform(-1.5, 1.5)

        forecast.append(
            {
                "timestamp": future_time.strftime("%Y-%m-%d %H:00"),
                "temperature_c": round(current_temp, 1),
            }
        )

    return {"city": city, "forecast_series": forecast}
